module cache_ram_8_64_8_1489f923c4dca729178b3e3233458550d8dddf29 (
`ifdef USE_POWER_PINS
   inout vccd1,
   inout vssd1,
`endif
   input  clk,
   input  rd_en,
   input  [7:0] rd_addr, // Changed to 8 bits for 256 rows
   input  [7:0] wr_sel,
   input  [7:0] wr_addr, // Changed to 8 bits for 256 rows
   input  [63:0] wr_data,
   output [63:0] rd_data
);

  // --- Internal Signals ---

  // Write port logic
  wire wr_enable;
  wire write_csb_s;
  wire write_web_s;

  // Read port logic
  wire read_csb_s;
  wire [63:0] sram_read_data; // Data output from the SRAM macro

  // Read data output pipeline (to match original 1-cycle latency)
  wire [63:0] rd_data0_saved;
  wire [63:0] rd_data0;
  wire rd_en_prev;
  
  reg [63:0] n29430_q; // Latency register for read data
  reg n29431_q;   // Latency register for read enable

  // --- Assignments ---

  assign rd_data = rd_data0;

  // Derive active-high write enable from byte-select mask
  assign wr_enable = |(wr_sel);

  // --- Port Mapping Logic ---

  // Write Port (Active Low)
  // Enable the chip select if any write selector bit is high
  assign write_csb_s = ~wr_enable;
  // This is a write-only port, so Write Enable Bar is always active (low)
  assign write_web_s = 1'b0; 

  // Read Port (Active Low)
  // Enable the read chip select when rd_en is high
  assign read_csb_s = ~rd_en;

  // --- SRAM Macro Instantiation ---

  sky130_sram_2kbyte_1rw1r_64x256_8 sram_inst (
  `ifdef USE_POWER_PINS
      .vccd1(vccd1),
      .vssd1(vssd1),
  `endif
      // Write Port
      .write_clk(clk),
      .write_csb(write_csb_s),
      .write_web(write_web_s),
      .write_wmask(wr_sel),
      .write_addr(wr_addr),
      .write_data(wr_data),
      .write_dout(), // Write port read-data is not used

      // Read Port
      .read_clk(clk),
      .read_csb(read_csb_s),
      .read_addr(rd_addr),
      .read_data(sram_read_data)
  );

  // --- Output Latency Logic (Preserved from original) ---
  
  // rd_data0_saved holds the value from the previous cycle
  assign rd_data0_saved = n29430_q; 
  // rd_en_prev holds the rd_en from the previous cycle
  assign rd_en_prev = n29431_q;   

  // Combinational Mux:
  // If read was enabled last cycle (rd_en_prev), present the new data
  // from the SRAM (sram_read_data). Otherwise, hold the old data.
  assign rd_data0 = rd_en_prev ? sram_read_data : rd_data0_saved;

  // Registered pipeline (1-cycle latency)
  // Latch the final data output
  always @(posedge clk)
    n29430_q <= rd_data0;
    
  // Latch the read enable
  always @(posedge clk)
    n29431_q <= rd_en;
    
endmodule

