module cache_ram_8_72_72_1489f923c4dca729178b3e3233458550d8dddf29 (
`ifdef USE_POWER_PINS
   vccd1,
   vssd1,
`endif
   clk,
   rd_en,
   rd_addr,
   wr_sel,
   wr_addr,
   wr_data,
   rd_data
);

`ifdef USE_POWER_PINS
   inout vccd1;
   inout vssd1;
`endif
   
   // --- Port Declarations (from original) ---
   input  clk;
   input  rd_en;     // Active-high read enable
   input  [7:0] rd_addr;
   input  wr_sel;    // Active-high write enable (for the whole 72-bit word)
   input  [7:0] wr_addr;
   input  [71:0] wr_data;
   output [71:0] rd_data;

   // --- Internal Signals for sky130 Macro ---
   
   // Write port signals
   wire write_csb_s;
   wire write_web_s;
   wire [8:0] write_wmask_s; // 9 bits for 9 bytes (72 bits)
   
   // Read port signals
   wire read_csb_s;
   wire [71:0] sram_read_data; // Data output from macro's read port

   // --- sky130 Port Logic ---

   // Map active-high wrapper enables to active-low macro enables
   assign write_csb_s = ~wr_sel;
   assign write_web_s = ~wr_sel; // Tie write-enable-bar to chip-select-bar
   assign read_csb_s  = ~rd_en;

   // Original module did a full 72-bit write.
   // Create a 9-bit write mask that is all '1's when writing.
   assign write_wmask_s = wr_sel ? 9'h1FF : 9'h000;

   // --- sky130 Macro Instantiation ---

   sky130_sram_2kbyte_1rw1r_72x256_8 sram_inst (
   `ifdef USE_POWER_PINS
      .vccd1(vccd1),
      .vssd1(vssd1),
   `endif
      // Write Port
      .write_clk(clk),
      .write_csb(write_csb_s),
      .write_web(write_web_s),
      .write_wmask(write_wmask_s),
      .write_addr(wr_addr),
      .write_data(wr_data),
      .write_dout(), // Write port read-data is not used

      // Read Port
      .read_clk(clk),
      .read_csb(read_csb_s),
      .read_addr(rd_addr),
      .read_data(sram_read_data)
   );

   // --- Output Latency Logic (to match original) ---
   
   // Replicate the 1-cycle read latency from the original module.
   // The output register only samples the SRAM's output when rd_en is high.
   reg [71:0] rd_data_reg;

   always @(posedge clk) begin
      if (rd_en) begin
         rd_data_reg <= sram_read_data;
      end
   end
   
   assign rd_data = rd_data_reg;

endmodule

